def execute(arguments):
    """
    格式化数据

    参数:
        arguments (dict): 包含以下字段
            - data (any): 要格式化的数据，必填，可以是字典、列表或JSON字符串
            - format (str): 输出格式，"json"（默认）、"csv"、"table"
            - indent (int): JSON缩进空格数，默认 2

    返回:
        dict: 包含格式化结果的字典
            - success (bool): 是否成功
            - result (str): 格式化后的字符串
            - error (str): 错误信息（失败时）
    """
    import json

    data = arguments.get("data")
    format_type = arguments.get("format", "json")
    indent = arguments.get("indent", 2)

    if data is None:
        return {"success": False, "error": "请提供要格式化的数据"}

    try:
        if format_type == "json":
            if isinstance(data, str):
                data = json.loads(data)
            result = json.dumps(data, ensure_ascii=False, indent=indent)
        elif format_type == "csv":
            if not isinstance(data, list):
                return {"success": False, "error": "CSV格式需要列表数据"}

            if not data:
                result = ""
            elif isinstance(data[0], dict):
                headers = list(data[0].keys())
                lines = [",".join(headers)]
                for item in data:
                    row = [str(item.get(h, "")) for h in headers]
                    lines.append(",".join(row))
                result = "\n".join(lines)
            else:
                result = "\n".join([str(item) for item in data])
        elif format_type == "table":
            if not isinstance(data, list):
                return {"success": False, "error": "表格格式需要列表数据"}

            if not data:
                result = "空表格"
            elif isinstance(data[0], dict):
                headers = list(data[0].keys())
                col_widths = [len(h) for h in headers]

                for item in data:
                    for i, h in enumerate(headers):
                        col_widths[i] = max(col_widths[i], len(str(item.get(h, ""))))

                separator = "+" + "+".join(["-" * (w + 2) for w in col_widths]) + "+"
                header_row = "|" + "|".join([f" {h:<{col_widths[i]}} " for i, h in enumerate(headers)]) + "|"

                lines = [separator, header_row, separator]
                for item in data:
                    row = "|" + "|".join([f" {str(item.get(h, '')):<{col_widths[i]}} " for i, h in enumerate(headers)]) + "|"
                    lines.append(row)
                lines.append(separator)
                result = "\n".join(lines)
            else:
                result = "\n".join([str(item) for item in data])
        else:
            return {"success": False, "error": f"不支持的格式: {format_type}"}

        return {"success": True, "result": result}
    except Exception as e:
        return {"success": False, "error": f"格式化失败: {str(e)}"}
